const EMBEDDED_APP_HTML = EMBEDDED_APP_JS;
const EMBEDDED_APP_CSS = "/* NexusGram minimal */\nbody{margin:0;background:#050b12;color:#e8f7ff;font-family:system-ui,sans-serif;}";

const LOGO_WEBP_B64 = '';
const JSON_HEADERS = { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' };
const MAX_INIT_AGE = 60 * 60 * 24;
const START_ENERGY = 1000;
const REGEN_PER_TICK = 5;
const REGEN_INTERVAL_MS = 60 * 60 * 1000;
const DAILY_BONUS = 50;
const UPGRADE_BASE = { multitap: 100, energy: 150, recharge: 125 };

function json(data, status=200){ return new Response(JSON.stringify(data), {status, headers:JSON_HEADERS}); }
function fail(message,status=400){ return json({error:message},status); }
async function hmac(keyBytes, message){ const key=await crypto.subtle.importKey('raw',keyBytes,{name:'HMAC',hash:'SHA-256'},false,['sign']); return new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(message))); }
function hex(bytes){return [...bytes].map(b=>b.toString(16).padStart(2,'0')).join('')}
function b64urlBytes(value){const s=String(value||'').replace(/-/g,'+').replace(/_/g,'/');const pad=s.length%4?s+'='.repeat(4-s.length%4):s;const bin=atob(pad);const out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out}
async function verifyTelegramSignature(params,botId){
  const sig=String(params.get('signature')||'').trim();
  if(!sig||!botId)return false;
  params.delete('signature');params.delete('hash');
  params.sort();
  const data=String(botId)+':WebAppData\n'+[...params.entries()].map(([k,v])=>k+'='+v).join('\n');
  const key=await crypto.subtle.importKey('raw',hexBytes('e7bf03a2fa4602af4580703d88dda5bb59f32ed8b02a56c187fe7d34caed242d'),{name:'Ed25519'},false,['verify']);
  return crypto.subtle.verify({name:'Ed25519'},key,b64urlBytes(sig),new TextEncoder().encode(data));
}
function hexBytes(hexString){const out=new Uint8Array(hexString.length/2);for(let i=0;i<out.length;i++)out[i]=parseInt(hexString.slice(i*2,i*2+2),16);return out}
function safeEqual(a,b){if(a.length!==b.length)return false;let d=0;for(let i=0;i<a.length;i++)d|=a.charCodeAt(i)^b.charCodeAt(i);return d===0}
function normalizeBotToken(value){
  let token=String(value||'').trim().replace(/^['"]|['"]$/g,'').replace(/^Bearer\s+/i,'').trim();
  const m=token.match(/api\.telegram\.org\/bot([^/\s]+)/i);
  if(m)token=m[1];
  token=token.replace(/^bot/i,'').replace(/\s+/g,'');
  return token.trim();
}
async function verifyInitData(initData,botToken){
  initData=String(initData||'').trim();
  botToken=normalizeBotToken(botToken);
  if(!botToken)throw new Error('Telegram BOT_TOKEN is not configured on the worker. Set the BOT_TOKEN secret.');
  if(!initData)throw new Error('Telegram launch data missing. Open the Mini App from the bot.');
  const params=new URLSearchParams(initData);
  const receivedHash=String(params.get('hash')||'').trim().toLowerCase();
  const receivedSig=String(params.get('signature')||'').trim();
  if(!receivedHash && !receivedSig)throw new Error('Invalid Telegram launch data (no hash/signature)');
  // Build data-check-string: exclude both hash and signature (Bot API 8.0+)
  const checkParams=new URLSearchParams(initData);
  checkParams.delete('hash');
  checkParams.delete('signature');
  const authDate=Number(checkParams.get('auth_date')||0);
  const nowSec=Math.floor(Date.now()/1000);
  // Allow small clock skew (5 min) and max age
  if(!authDate || nowSec-authDate>MAX_INIT_AGE || authDate-nowSec>300)throw new Error('Telegram session expired. Close and reopen the Mini App from the bot.');
  checkParams.sort();
  const check=[...checkParams.entries()].map(([k,v])=>k+'='+v).join('\n');
  // Official: secret_key = HMAC_SHA256(key="WebAppData", message=bot_token)
  let hmacOk=false;
  if(receivedHash){
    const secret=await hmac(new TextEncoder().encode('WebAppData'), botToken);
    const expected=hex(await hmac(secret, check));
    hmacOk=safeEqual(expected, receivedHash);
  }
  if(!hmacOk){
    // Fallback / alternative: Ed25519 signature (Bot API 8.0+ third-party style)
    let edOk=false;
    try{
      const meRes=await fetch('https://api.telegram.org/bot'+botToken+'/getMe');
      const td=await meRes.json().catch(()=>({}));
      if(td.ok && td.result?.id){
        if(receivedSig){
          edOk = await verifyTelegramSignature(new URLSearchParams(initData), td.result.id);
        }
        if(!edOk && receivedHash){
          // Last chance: maybe token is for a different bot — report clear error
          throw new Error('Telegram signature mismatch. BOT_TOKEN belongs to @'+String(td.result?.username||'unknown')+' but initData hash did not match. Ensure the Mini App is opened from the same bot whose token is configured.');
        }
        if(!edOk){
          throw new Error('Telegram signature verification failed. Reopen the Mini App from @'+String(td.result?.username||'Nexusgram_official_bot')+'.');
        }
      } else if(String(td.description||'').includes('Not Found') || td.error_code===401){
        throw new Error('Telegram BOT_TOKEN is invalid or revoked. Update the BOT_TOKEN secret to the token of your official bot.');
      } else {
        throw new Error('Telegram signature verification failed ('+(td.description||'unknown')+')');
      }
    }catch(e){
      const msg=String(e?.message||e||'');
      if(msg.startsWith('Telegram '))throw e;
      throw new Error('Telegram signature verification failed');
    }
  }
  let user;
  try{user=JSON.parse(checkParams.get('user')||'{}')}catch{throw new Error('Invalid Telegram user data')}
  if(!user.id)throw new Error('Telegram user missing');
  return {user,startParam:checkParams.get('start_param')||''};
}
function energyState(row,now,depletedAt,regenIntervalMs=REGEN_INTERVAL_MS){
  const max=Number(row.max_energy||START_ENERGY);
  const current=Math.max(0,Number(row.energy||0));
  const rechargeLevel=Math.max(0,Number(row.recharge_level||0));
  // Base 1 hour; each recharge level shortens wait ~12% (min 15 min)
  const interval=Math.max(5*60*1000, Math.floor(regenIntervalMs / (1 + 0.12 * rechargeLevel)));
  if(current<=0){
    const anchor=Number(depletedAt||now);
    const readyAt=anchor+interval;
    if(now>=readyAt)return {energy:max,max,regen:0,ticks:0,nextRegenAt:0,ready:true,interval};
    return {energy:0,max,regen:0,ticks:0,nextRegenAt:readyAt,ready:false,interval};
  }
  return {energy:Math.min(max,current),max,regen:0,ticks:0,nextRegenAt:0,ready:false,interval};
}
function rankFromPoints(p,cfg){const c=cfg||{};const t=[{n:'Grandmaster',m:Number(c.rank_grandmaster||300000)},{n:'Master',m:Number(c.rank_master||150000)},{n:'Diamond',m:Number(c.rank_diamond||75000)},{n:'Platinum',m:Number(c.rank_platinum||35000)},{n:'Gold',m:Number(c.rank_gold||15000)},{n:'Silver',m:Number(c.rank_silver||5000)},{n:'Bronze',m:Number(c.rank_bronze||1000)},{n:'Rookie',m:0}];for(const x of t){if(Number(p||0)>=x.m)return x.n;}return 'Rookie';}
function userShape(row,referralCount=0,taskStatus={}){const multi=Number(row.multitap_level||0),energy=Number(row.energy_level||0),recharge=Number(row.recharge_level||0);return {telegramId:String(row.telegram_id),firstName:row.first_name||'Miner',username:row.username||'',photoUrl:String(row.photo_url||''),photo_url:String(row.photo_url||''),points:Number(row.points||0),energy:Number(row.energy||0),maxEnergy:Number(row.max_energy||START_ENERGY),tapPower:1+multi,streak:Number(row.streak||0),referralCount,rank:rankFromPoints(Number(row.points||0)),taskStatus,upgrades:{multitap:multi,energy,recharge},upgradeCosts:{multitap:Math.ceil(UPGRADE_BASE.multitap*Math.pow(1.65,multi)),energy:Math.ceil(UPGRADE_BASE.energy*Math.pow(1.65,energy)),recharge:Math.ceil(UPGRADE_BASE.recharge*Math.pow(1.65,recharge))}}}
async function getUser(env,id){return await env.DB.prepare('SELECT * FROM users WHERE telegram_id=?').bind(String(id)).first()}
async function auth(request,env,body){const data=body||{};const initData=data.initData||new URL(request.url).searchParams.get('initData')||'';const verified=await verifyInitData(initData,env.BOT_TOKEN);if(await isUserBlocked(env,verified.user.id))throw new Error('Your account is restricted. Contact NexusGram support.');return verified}

async function fetchTelegramPhotoUrl(env, userId){
  try{
    const token=normalizeBotToken(env.BOT_TOKEN);
    if(!token||!userId)return '';
    const r=await fetch('https://api.telegram.org/bot'+token+'/getUserProfilePhotos?user_id='+encodeURIComponent(String(userId))+'&limit=1');
    const j=await r.json().catch(()=>({}));
    const sizes=j?.result?.photos?.[0];
    if(!Array.isArray(sizes)||!sizes.length)return '';
    const best=sizes[sizes.length-1];
    const fileId=best?.file_id;
    if(!fileId)return '';
    const fr=await fetch('https://api.telegram.org/bot'+token+'/getFile?file_id='+encodeURIComponent(fileId));
    const fj=await fr.json().catch(()=>({}));
    const path=fj?.result?.file_path;
    if(!path)return '';
    // Store stable app proxy path (token never exposed to client)
    return '/api/avatar/'+String(userId);
  }catch(e){return ''}
}
async function ensureUser(env,verified){const id=String(verified.user.id);let row=await getUser(env,id);const now=Date.now();
let photo=String(verified.user.photo_url||verified.user.photoUrl||row?.photo_url||'').slice(0,500);
if(!row){const first=String(verified.user.first_name||'Miner').slice(0,64);const startE=Math.max(100,Math.min(100000,Number(await readAdminSetting(env,'start_energy',String(START_ENERGY)))||START_ENERGY));await env.DB.prepare('INSERT OR IGNORE INTO users (telegram_id,first_name,username,points,energy,max_energy,updated_at,created_at) VALUES (?,?,?,?,?,?,?,?)').bind(id,first,String(verified.user.username||'').slice(0,64),0,startE,startE,now,now).run();if(photo){try{await env.DB.prepare('UPDATE users SET photo_url=? WHERE telegram_id=?').bind(photo,id).run()}catch(e){}}row=await getUser(env,id);}else{if(photo){await env.DB.prepare('UPDATE users SET first_name=?,username=?,photo_url=? WHERE telegram_id=?').bind(String(verified.user.first_name||row.first_name||'Miner').slice(0,64),String(verified.user.username||row.username||'').slice(0,64),photo,id).run();}else{await env.DB.prepare('UPDATE users SET first_name=?,username=? WHERE telegram_id=?').bind(String(verified.user.first_name||row.first_name||'Miner').slice(0,64),String(verified.user.username||row.username||'').slice(0,64),id).run();}row=await getUser(env,id);}const match=String(verified.startParam||'').match(/^(?:nxg_ref_)?(\d{1,20})$/);if((await readAdminSetting(env,'referrals_enabled','1'))==='1'&&match&&match[1]!==id&&!row.referred_by){const inviter=await getUser(env,match[1]);if(inviter&&String(inviter.telegram_id)!==id){await env.DB.batch([env.DB.prepare('INSERT OR IGNORE INTO referrals (inviter_id,invitee_id,created_at,active) VALUES (?,?,?,0)').bind(match[1],id,now),env.DB.prepare('UPDATE users SET referred_by=? WHERE telegram_id=? AND referred_by IS NULL').bind(match[1],id)]);row=await getUser(env,id);}}return row}
function indiaDay(date=Date.now()){return new Date(Number(date)+19800000).toISOString().slice(0,10)}
async function refreshed(env,row){
 const now=Date.now();
 const id=row.telegram_id;
 // One-time schema ensures (cached per isolate)
 if(!globalThis.__nxgSchemaReady){
  await env.DB.batch([
   env.DB.prepare('CREATE TABLE IF NOT EXISTS energy_cycles (telegram_id TEXT PRIMARY KEY, depleted_at INTEGER NOT NULL)'),
   env.DB.prepare('CREATE TABLE IF NOT EXISTS task_claims_v3 (telegram_id TEXT NOT NULL, task TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(telegram_id,task))')
  ]);
  try{await env.DB.prepare('INSERT OR IGNORE INTO task_claims_v3 (telegram_id,task,created_at) SELECT telegram_id,task,MIN(created_at) FROM task_claims_v2 GROUP BY telegram_id,task').run()}catch{}
  try{await env.DB.prepare('INSERT OR IGNORE INTO task_claims_v3 (telegram_id,task,created_at) SELECT telegram_id,task,MIN(created_at) FROM task_claims GROUP BY telegram_id,task').run()}catch{}
  globalThis.__nxgSchemaReady=true;
 }
 const [cycle, refs, daily, taskRows, lastDaily, regenHoursRaw, maxEnergyRaw, energyCostRaw, tapRewardRaw, multiBaseRaw, energyBaseRaw, rechargeBaseRaw, adRewardRaw, dailyCooldownRaw] = await Promise.all([
  env.DB.prepare('SELECT depleted_at FROM energy_cycles WHERE telegram_id=?').bind(id).first(),
  env.DB.prepare('SELECT COUNT(*) AS n FROM referrals WHERE inviter_id=?').bind(id).first(),
  env.DB.prepare('SELECT id FROM daily_claims WHERE telegram_id=? AND claim_day=? LIMIT 1').bind(id,indiaDay(now)).first(),
  env.DB.prepare('SELECT task FROM task_claims_v3 WHERE telegram_id=?').bind(id).all(),
  env.DB.prepare('SELECT created_at FROM daily_claims WHERE telegram_id=? ORDER BY created_at DESC LIMIT 1').bind(id).first(),
  readAdminSetting(env,'energy_regen_hours','1'),
  readAdminSetting(env,'start_energy','2000'),
  readAdminSetting(env,'energy_cost','10'),
  readAdminSetting(env,'tap_reward','1'),
  readAdminSetting(env,'multitap_base_cost',String(UPGRADE_BASE.multitap)),
  readAdminSetting(env,'energy_base_cost',String(UPGRADE_BASE.energy)),
  readAdminSetting(env,'recharge_base_cost',String(UPGRADE_BASE.recharge)),
  readAdminSetting(env,'ad_reward','50'),
  readAdminSetting(env,'daily_cooldown_hours','24')
 ]);
 let cycleRow=cycle;
 if(Number(row.energy||0)<=0&&!cycleRow){
  await env.DB.prepare('INSERT OR IGNORE INTO energy_cycles (telegram_id,depleted_at) VALUES (?,?)').bind(id,now).run();
  cycleRow=await env.DB.prepare('SELECT depleted_at FROM energy_cycles WHERE telegram_id=?').bind(id).first();
 }
 const regenHours=Math.max(0.25,Math.min(168,Number(regenHoursRaw||1)));
 const configuredMaxEnergy=Math.max(100,Math.min(10000000,Math.floor(Number(maxEnergyRaw||2000))));
 const currentEnergy=Math.max(0,Math.min(configuredMaxEnergy,Number(row.energy||0)));
 if(Number(row.max_energy||0)!==configuredMaxEnergy||Number(row.energy||0)!==currentEnergy){
  await env.DB.prepare('UPDATE users SET max_energy=?,energy=?,updated_at=? WHERE telegram_id=?').bind(configuredMaxEnergy,currentEnergy,now,id).run();
  row.max_energy=configuredMaxEnergy;row.energy=currentEnergy;
 }
 const e=energyState(row,now,Number(cycleRow?.depleted_at||0),regenHours*3600000);
 if(e.ready){
  await env.DB.prepare('UPDATE users SET energy=? WHERE telegram_id=? AND energy<=0').bind(e.energy,id).run();
  await env.DB.prepare('DELETE FROM energy_cycles WHERE telegram_id=?').bind(id).run();
 }else if(Number(row.energy||0)>0&&cycleRow){
  await env.DB.prepare('DELETE FROM energy_cycles WHERE telegram_id=?').bind(id).run();
 }
 const updated=await getUser(env,id);
 const taskStatus={};
 for(const x of (taskRows.results||[])) taskStatus[String(x.task)]=true;
 const lastDailyAt=Number(lastDaily?.created_at||0);
 const dailyCooldownHours=Math.max(1,Math.min(720,Number(dailyCooldownRaw||24)));
 const nextDailyAt=lastDailyAt?lastDailyAt+dailyCooldownHours*3600000:0;
 const shaped=userShape(updated,Number(refs?.n||0),taskStatus);
 shaped.lastDailyClaimed=!!(nextDailyAt&&now<nextDailyAt);
 shaped.lastDailyClaimAt=lastDailyAt;
 shaped.nextDailyAt=nextDailyAt;
 shaped.nextEnergyAt=e.nextRegenAt;
 shaped.regenPerTick=e.regen;
 shaped.energyCost=Math.max(1,Math.min(100,Number(energyCostRaw||10)));
 const tapRewardSetting=Math.max(0,Math.min(100,Number(tapRewardRaw||1)));
 shaped.tapReward=tapRewardSetting;
 shaped.tapPower=Math.round((tapRewardSetting+Number(updated.multitap_level||0))*1e6)/1e6;
 const mb=Math.max(0,Math.min(100000000,Number(multiBaseRaw||UPGRADE_BASE.multitap)));
 const eb=Math.max(0,Math.min(100000000,Number(energyBaseRaw||UPGRADE_BASE.energy)));
 const rb=Math.max(0,Math.min(100000000,Number(rechargeBaseRaw||UPGRADE_BASE.recharge)));
 shaped.upgradeCosts={multitap:Math.ceil(mb*Math.pow(1.65,Number(row.multitap_level||0))),energy:Math.ceil(eb*Math.pow(1.65,Number(row.energy_level||0))),recharge:Math.ceil(rb*Math.pow(1.65,Number(row.recharge_level||0)))};
 shaped.adReward=Math.max(0,Math.min(100000,Number(adRewardRaw||50)));
 return shaped;
}
async function activateReferralIfEligible(env,id){
 const row=await getUser(env,id);
 if((await readAdminSetting(env,'referrals_enabled','1'))!=='1')return;
 const activationThreshold=Math.max(0,Math.min(100000000,Number(await readAdminSetting(env,'referral_activation_threshold','500'))));
 if(!row||Number(row.points||0)<activationThreshold)return;
 const referralBonus=Math.max(0,Math.min(100000,Number(await readAdminSetting(env,'referral_bonus','500'))));
 await env.DB.batch([
  env.DB.prepare('UPDATE users SET points=points+? WHERE telegram_id=(SELECT inviter_id FROM referrals WHERE invitee_id=? AND active=0 AND bonus_awarded=0)').bind(referralBonus,id),
  env.DB.prepare('UPDATE referrals SET active=1,bonus_awarded=1 WHERE invitee_id=? AND active=0 AND bonus_awarded=0').bind(id)
 ]);
}
